2872	bool vmap_view_render_pump(vmap_view_t * view, unsigned max_tiles)
2873	{
2874	    unsigned n;
2875	    uint32_t t0;
2876	
2877	    if (!view || !view->canvas || !view->cbuf || myvendor_mtp_lfs_quiesce()) {
2878	        return true;
2879	    }
2880	
2881	    if (view->pump_phase == 0) {
2882	        /* 没有帧在飞 ⇒ 泵本来就不该被调用（帧结束后定时器自己暂停）。
2883	         * **基准必须作废**，否则下一帧的第一拍会把"这一整段空闲"算成"UI 线程被占住"
2884	         * —— 第一版就是这么误报的：`SLOW pump gap 9471ms` / `2228ms` 其实都是
2885	         * "这段时间没渲染"（同期 BLE 每 10 秒的心跳照打，证明系统是活的）。 */
2886	        s_pf_last_pump_cyc = 0u;
2887	        return true;
2888	    }
2889	
2890	    if (max_tiles == 0) {
2891	        max_tiles = VMAP_RENDER_PUMP_MAX_TILES;
2892	    }
2893	
2894	    t0 = lv_tick_get();
2895	    myvendor_watchdog_ui_beat();
2896	    /* 单拍间隔超长 ⇒ **无条件** WARNING（正常帧不受影响）。只在这一帧确实在飞时量，
2897	     * 所以"没渲染的空闲"不会被算进来；而帧内一次 2 秒以上的拍间隔就只能是系统级
2898	     * 停顿（现场两次 WDT 饥饿复位都伴随 1.6~12 秒的这类间隔，且当时 [vperf] 正被
2899	     * 降到 debug、整场不可诊断）。 */
2900	    {
2901	        const uint32_t now_cyc = vmap_perf_cyc();
2902	
2903	        if (s_pf_last_pump_cyc != 0u && now_cyc - s_pf_last_pump_cyc
2904	            > VMAP_PERF_SLOW_GAP_MS * 240u * 1000u) {
2905	            syslog(LOG_WARNING,
2906	                "[vperf] SLOW pump gap %ums (>%ums) —— 帧内拍间隔异常，UI 线程被占住；若同时 WDT 停喂即饥饿族",
2907	                (unsigned)((now_cyc - s_pf_last_pump_cyc) / 240000u),
2908	                (unsigned)VMAP_PERF_SLOW_GAP_MS);
2909	            vmap_perf_dump_runnable();
2910	        }
2911	        s_pf_last_pump_cyc = now_cyc;
2912	    }
2913	
2914	    for (n = 0; n < max_tiles && view->pump_phase != 0; n++) {
2915	        if (n > 0 && lv_tick_elaps(t0) >= VMAP_RENDER_PUMP_BUDGET_MS) {
2916	            break;
2917	        }
2918	        if (!render_next_tile(view)) {
2919	            render_finish(view);
2920	            break;
2921	        }
2922	        if (lv_tick_elaps(t0) >= VMAP_RENDER_PUMP_BUDGET_MS) {
2923	            break;
2924	        }
2925	    }
2926	
2927	    return view->pump_phase == 0;
2928	}
