534	/*
535	 * Hidden map + REC: points stay in RAM. Returning always starts one fresh,
536	 * phased frame at the latest fix; never mix the stale pixel origin with new
537	 * route/track projections. Normal visible-page catchup may still use a small
538	 * restamp/tail update.
539	 */
540	static void map_page_catchup_visible(map_page_t * page)
541	{
542	    const bicycle_runtime_t * rt;
543	
544	    if (!page || !page->map || page->covered || !page->map_ui_visible) {
545	        return;
546	    }
547	
548	    if (vmap_view_render_revision(page->map) == 0) {
549	        page->map_refresh_pending = true;
550	        return;
551	    }
552	    if (vmap_view_render_busy(page->map)) {
553	        map_page_kick_render(page);
554	        return;
555	    }
556	
557	    rt = bicycle_runtime_get();
558	    if (rt && rt->gnss_valid) {
559	        vmap_view_set_center(page->map, (double)rt->longitude,
560	            (double)rt->latitude);
561	        vmap_view_update_arrow(page->map, (double)rt->longitude,
562	            (double)rt->latitude, rt->course_deg);
563	        page->map_last_follow_ms = lv_tick_get();
564	        map_page_kick_render(page);
565	    }
566	    if (vmap_view_render_busy(page->map)) {
567	        return;
568	    }
569	
570	#if VMAP_ROUTE_ENABLE
571	    if (page->route && vmap_route_is_active(page->route)) {
572	        map_page_stamp_route_overlay(page);
573	        return;
574	    }
575	#endif
576	#if VMAP_TRACK_ENABLE
577	    if (page->track) {
578	        vmap_track_refresh(page->track);
579	    }
580	#endif
581	}
