621	/**
622	 * @brief 首帧淡入 exec：画布 0→COVER，占位 COVER→0（同一条动画）。
623	 *
624	 * @details var 是 map_page 而不是某块画布：正北 / 航向朝上两条显示路径在这里合并，
625	 *          两块画布一起复位；销毁时也能按 page 一次删掉，不留半个状态。
626	 */
627	static void map_page_first_fade_exec(void * var, int32_t v)
628	{
629	    map_page_t * page = (map_page_t *)var;
630	    lv_opa_t opa;
631	
632	    if (page == NULL || helm_anim_is_suspended()) {
633	        return;
634	    }
635	
636	    if (v <= (int32_t)LV_OPA_TRANSP) {
637	        opa = LV_OPA_TRANSP;
638	    } else if (v >= (int32_t)LV_OPA_COVER) {
639	        opa = LV_OPA_COVER;
640	    } else {
641	        opa = (lv_opa_t)v;
642	    }
643	
644	    if (page->map_reveal_canvas != NULL) {
645	        lv_obj_set_style_opa(page->map_reveal_canvas, opa, 0);
646	    }
647	    if (page->map_reveal_rcanvas != NULL) {
648	        lv_obj_set_style_opa(page->map_reveal_rcanvas, opa, 0);
649	    }
650	    if (page->map_placeholder != NULL) {
651	        lv_obj_set_style_opa(page->map_placeholder,
652	            (lv_opa_t)(LV_OPA_COVER - opa), 0);
653	    }
654	}
