660	 *          淡出后连对象一起删，后续页面/主题不再有它的开销。
661	 */
662	static void map_page_first_fade_done(lv_anim_t * a)
663	{
664	    map_page_t * page = (a != NULL) ? (map_page_t *)a->var : NULL;
665	
666	    if (page == NULL) {
667	        return;
668	    }
669	
670	    if (page->map_reveal_canvas != NULL) {
671	        lv_obj_set_style_opa(page->map_reveal_canvas, LV_OPA_COVER, 0);
672	    }
673	    if (page->map_reveal_rcanvas != NULL) {
674	        lv_obj_set_style_opa(page->map_reveal_rcanvas, LV_OPA_COVER, 0);
675	    }
676	    if (page->map_placeholder != NULL) {
677	        lv_obj_delete(page->map_placeholder);
678	        page->map_placeholder = NULL;
679	        page->map_placeholder_lbl = NULL;
680	    }
681	    page->map_reveal_canvas = NULL;
682	    page->map_reveal_rcanvas = NULL;
683	}
