685	/**
686	 * @brief 首帧收帧：画布淡入 + 占位淡出（一次 180 ms 动画，用完即删）。
687	 *
688	 * @details 唯一入口是 on_render_pump() 里 vmap_view_render_pump() 报告整帧完成的
689	 *          那一拍（render_finish() 只清 HIDDEN，不会自己带过渡）。正北的 canvas 与
690	 *          航向朝上的 rcanvas 在这里收敛成同一条路径。之后 map_first_shown 为 true，
691	 *          每帧只多一次 bool 判断；动画结束不留定时器，占位对象也删掉。
692	 */
693	static void map_page_reveal_first_frame(map_page_t * page)
694	{
695	    lv_anim_t a;
696	
697	    if (page == NULL || page->map == NULL || page->map_first_shown) {
698	        return;
699	    }
700	    /* pump 在 LFS hold 等路径会提前返回 true 而没走到 render_finish：以帧计数为准。 */
701	    if (vmap_view_render_revision(page->map) == 0u) {
702	        return;
703	    }
704	
705	    if (page->map_reveal_canvas == NULL) {
706	        page->map_reveal_canvas = vmap_view_get_obj(page->map);
707	    }
708	    if (page->map_reveal_rcanvas == NULL) {
709	        page->map_reveal_rcanvas = map_page_rot_canvas(page);
710	    }
711	    page->map_first_shown = true;
712	
713	    lv_anim_init(&a);
714	    lv_anim_set_var(&a, page);
715	    lv_anim_set_values(&a, (int32_t)LV_OPA_TRANSP, (int32_t)LV_OPA_COVER);
716	    lv_anim_set_duration(&a, MAP_PAGE_FIRST_FADE_MS);
717	    lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
718	    lv_anim_set_exec_cb(&a, map_page_first_fade_exec);
719	    lv_anim_set_completed_cb(&a, map_page_first_fade_done);
720	    lv_anim_start(&a);
721	}
